from math import ceil, floor

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find non-background, non-bar color components.
    unseen = {(r, c) for r in range(h) for c in range(w)
              if grid[r][c] not in (0, 5)}
    components = []
    while unseen:
        start = unseen.pop()
        comp = {start}
        q = [start]
        while q:
            r, c = q.pop()
            for p in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if p in unseen:
                    unseen.remove(p); comp.add(p); q.append(p)
        components.append(comp)

    bars = []
    # Maximal horizontal 5-bars.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1; continue
            a = c
            while c < w and grid[r][c] == 5: c += 1
            if c-a > 1: bars.append(("H", r, a, c-1))
    # Maximal vertical 5-bars.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1; continue
            a = r
            while r < h and grid[r][c] == 5: r += 1
            if r-a > 1: bars.append(("V", c, a, r-1))

    for orient, fixed, lo, hi in bars:
        for comp in components:
            contacts = []
            for r, c in comp:
                if orient == "H":
                    if (r-1, c) in {(fixed, x) for x in range(lo, hi+1)} or (r+1, c) in {(fixed, x) for x in range(lo, hi+1)}:
                        contacts.append((r, c))
                else:
                    if (r, c-1) in {(x, fixed) for x in range(lo, hi+1)} or (r, c+1) in {(x, fixed) for x in range(lo, hi+1)}:
                        contacts.append((r, c))
            if not contacts:
                continue

            # The component attached to the bar is a seed motif. Repeat it in
            # translated copies along the bar, with period equal to its extent
            # along the bar's axis.
            axis_coords = [c if orient == "H" else r for r, c in comp]
            amin, amax = min(axis_coords), max(axis_coords)
            period = amax - amin + 1
            anchor = (contacts[0][1] if orient == "H" else contacts[0][0])
            base = amin
            first_k = ceil((lo - amax) / period)
            last_k = floor((hi - amin) / period)
            for k in range(first_k, last_k + 1):
                shift = k * period
                for r, c in comp:
                    rr, cc = (r, c + shift) if orient == "H" else (r + shift, c)
                    if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0:
                        out[rr][cc] = grid[r][c]
            break
    return out
